WITH matched_keys AS (SELECT status FROM orders INTERSECT ALL SELECT status FROM orders WHERE customer_id IS NOT NULL), kept_rows AS (SELECT s.* FROM orders s JOIN matched_keys k ON s.status = k.status) SELECT s.customer_id, s.store_id, s.status, s.channel, s.amount, s.shipping_fee, (SELECT MAX(t2.shipping_fee) FROM orders t2 WHERE t2.customer_id = s.customer_id) AS max_order_shipping_fee FROM kept_rows s ORDER BY shipping_fee DESC, status;
